-- =============================================================================
--  SECURITY, CONSTRAINTS AND FUNCTIONS (hand-written; appended to the init
--  migration after Prisma's generated tables)
-- =============================================================================
--
-- Supabase gives the browser direct access to Postgres through its API, with
-- the logged-in user's identity attached. That's only safe because of ROW
-- LEVEL SECURITY (RLS): every table below has RLS turned on, and a row is
-- invisible unless a policy explicitly allows it. "Deny by default."
--
-- auth.uid() is Supabase's function that returns the id of the user making
-- the request (from their login token). We write (select auth.uid()) inside
-- policies so Postgres evaluates it once per query instead of once per row.
--
-- Roles: `authenticated` = a signed-in user, `anon` = not signed in.
-- Anonymous visitors get no access to anything.

-- btree_gist lets one index mix "equals" (user_id) with "overlaps" (time
-- ranges); the no-double-booking constraint below needs it. Supabase keeps
-- extensions in their own schema rather than public.
create schema if not exists extensions;
create extension if not exists btree_gist with schema extensions;

-- ---------------------------------------------------------------------------
-- 1. Data rules the schema language can't express
-- ---------------------------------------------------------------------------

-- Link each profile to its Supabase login. Deleting the account deletes
-- everything (profiles cascade to every other table).
alter table public.profiles
  add constraint profiles_id_fkey foreign key (id) references auth.users (id) on delete cascade;

alter table public.profiles
  add constraint profiles_handle_format check (handle ~ '^[a-z0-9_]{3,20}$'),
  add constraint profiles_display_name_not_blank check (length(trim(display_name)) > 0);

alter table public.user_settings
  add constraint user_settings_week_start check (week_starts_on between 1 and 7),
  add constraint user_settings_day_window check (
    day_start_minute between 0 and 1439
    and day_end_minute between 1 and 1440
    and day_end_minute - day_start_minute >= 60
  ),
  add constraint user_settings_lead check (reminder_lead_minutes between 0 and 120);

alter table public.events
  add constraint events_minutes check (start_minute between 0 and 1439 and end_minute between 1 and 1440 and end_minute > start_minute),
  add constraint events_dates check (end_date is null or end_date >= start_date),
  add constraint events_weekdays check (weekdays <@ array[1,2,3,4,5,6,7]::smallint[]),
  -- A one-off event (no weekdays) must start and end on the same date.
  add constraint events_one_off check (cardinality(weekdays) > 0 or end_date = start_date),
  add constraint events_title_not_blank check (length(trim(title)) > 0);

alter table public.tasks
  add constraint tasks_estimate check (estimated_minutes between 5 and 1440),
  add constraint tasks_min_session check (min_session_minutes between 5 and estimated_minutes),
  add constraint tasks_title_not_blank check (length(trim(title)) > 0);

alter table public.blocks
  add constraint blocks_time_order check (ends_at > starts_at),
  add constraint blocks_max_length check (ends_at - starts_at <= interval '12 hours'),
  -- The planner must never double-book you: no two of YOUR blocks may overlap.
  -- An exclusion constraint checks every insert/update against existing rows
  -- using a GiST index on (user, time range). [) = start inclusive, end exclusive,
  -- so a 9–10 block and a 10–11 block are allowed to touch.
  add constraint blocks_no_overlap exclude using gist (
    user_id with =,
    tstzrange(starts_at, ends_at, '[)') with &&
  );

alter table public.points_ledger
  add constraint points_ledger_range check (points between -1000 and 1000);

alter table public.friendships
  add constraint friendships_not_self check (requester_id <> addressee_id);

-- Only ONE friendship row per pair, whichever direction it was sent in.
create unique index friendships_pair_key on public.friendships
  (least(requester_id, addressee_id), greatest(requester_id, addressee_id));

alter table public.hangout_invites
  add constraint hangout_invites_not_self check (from_user_id <> to_user_id),
  add constraint hangout_invites_time_order check (ends_at > starts_at);

-- ---------------------------------------------------------------------------
-- 2. Triggers
-- ---------------------------------------------------------------------------

-- Keep updated_at honest no matter who writes (Prisma, supabase-js, SQL).
create function public.set_updated_at() returns trigger
language plpgsql set search_path = '' as $$
begin
  new.updated_at := now();
  return new;
end $$;

create trigger set_updated_at before update on public.user_settings
  for each row execute function public.set_updated_at();
create trigger set_updated_at before update on public.events
  for each row execute function public.set_updated_at();
create trigger set_updated_at before update on public.tasks
  for each row execute function public.set_updated_at();

-- Reject made-up time zones. A CHECK constraint can't look things up in
-- another table, so a trigger compares against Postgres's own zone list.
create function public.validate_time_zone() returns trigger
language plpgsql set search_path = '' as $$
begin
  if not exists (select 1 from pg_catalog.pg_timezone_names where name = new.time_zone) then
    raise exception 'Unknown time zone: %', new.time_zone using errcode = '22023';
  end if;
  return new;
end $$;

create trigger validate_time_zone before insert or update of time_zone on public.user_settings
  for each row execute function public.validate_time_zone();

-- When someone signs up (a row appears in auth.users), create their profile
-- and settings automatically. SECURITY DEFINER = runs with the function
-- owner's rights, because the new user can't insert profiles themselves.
-- `set search_path = ''` (and fully qualified names) stops anyone from
-- hijacking the function by creating look-alike tables in another schema.
create function public.handle_new_user() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  tz text := coalesce(new.raw_user_meta_data ->> 'time_zone', 'UTC');
begin
  if not exists (select 1 from pg_catalog.pg_timezone_names where name = tz) then
    tz := 'UTC';
  end if;

  insert into public.profiles (id, display_name, handle)
  values (
    new.id,
    left(coalesce(nullif(trim(new.raw_user_meta_data ->> 'display_name'), ''), split_part(new.email, '@', 1), 'New user'), 50),
    -- A guaranteed-unique starter handle; users can pick a nicer one later.
    'user_' || substr(replace(new.id::text, '-', ''), 1, 12)
  );

  insert into public.user_settings (user_id, time_zone) values (new.id, tz);
  return new;
end $$;

create trigger on_auth_user_created after insert on auth.users
  for each row execute function public.handle_new_user();

-- ---------------------------------------------------------------------------
-- 3. Privileges: what each role may attempt at all (RLS then filters rows)
-- ---------------------------------------------------------------------------

revoke all on all tables in schema public from anon, authenticated;

-- Profiles: column-level SELECT so nobody (not even you, directly) reads
-- invite codes from the table. Your own code comes from my_invite_code().
grant select (id, display_name, handle, avatar_color, created_at) on public.profiles to authenticated;
-- Users may rename themselves but never rewrite their id or invite code.
grant update (display_name, handle, avatar_color) on public.profiles to authenticated;
grant select, update on public.user_settings to authenticated;
grant select, insert, update, delete on public.events to authenticated;
grant select, insert, update, delete on public.tasks to authenticated;
grant select, insert, update, delete on public.blocks to authenticated;
grant select on public.points_ledger to authenticated;           -- read-only!
grant select, delete on public.friendships to authenticated;      -- create/accept via functions
grant select, insert, delete on public.hangout_invites to authenticated;
-- Column-level grant: the recipient may only change the response fields,
-- never who it's from, the time, or the message.
grant update (status, responded_at) on public.hangout_invites to authenticated;

-- ---------------------------------------------------------------------------
-- 4. Row-level security policies
-- ---------------------------------------------------------------------------

alter table public.profiles enable row level security;
alter table public.user_settings enable row level security;
alter table public.events enable row level security;
alter table public.tasks enable row level security;
alter table public.blocks enable row level security;
alter table public.points_ledger enable row level security;
alter table public.friendships enable row level security;
alter table public.hangout_invites enable row level security;

-- Is there an ACCEPTED friendship between a and b?
-- SECURITY DEFINER so policies can call it without tripping over the
-- friendships table's own RLS (and without recursion). It only answers when
-- the caller is one of the two people, so nobody can probe who's friends
-- with whom.
create function public.are_friends(a uuid, b uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from public.friendships f
    where f.status = 'accepted'
      and (select auth.uid()) in (a, b)
      and least(f.requester_id, f.addressee_id) = least(a, b)
      and greatest(f.requester_id, f.addressee_id) = greatest(a, b)
  );
$$;

-- Any friendship row (pending or accepted) between a and b?
create function public.has_friendship(a uuid, b uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from public.friendships f
    where (select auth.uid()) in (a, b)
      and least(f.requester_id, f.addressee_id) = least(a, b)
      and greatest(f.requester_id, f.addressee_id) = greatest(a, b)
  );
$$;

-- PROFILES: you see yourself, and people you have a friendship/request with.
-- (Invite codes are hidden by the column-level grant in section 3.)
create policy "profiles: read self and connections" on public.profiles
  for select to authenticated
  using (id = (select auth.uid()) or public.has_friendship(id, (select auth.uid())));

create policy "profiles: update self" on public.profiles
  for update to authenticated
  using (id = (select auth.uid())) with check (id = (select auth.uid()));

-- SETTINGS: strictly private.
create policy "settings: own row" on public.user_settings
  for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

-- EVENTS and TASKS: strictly private. Friends see busy TIMES only, through
-- friend_busy_intervals() below, never these rows.
create policy "events: own rows" on public.events
  for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

create policy "tasks: own rows" on public.tasks
  for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

-- BLOCKS: private, AND the task must be yours too. Without the second check
-- someone could attach a block to another user's task id.
create policy "blocks: own rows" on public.blocks
  for all to authenticated
  using (user_id = (select auth.uid()))
  with check (
    user_id = (select auth.uid())
    and exists (select 1 from public.tasks t where t.id = task_id and t.user_id = (select auth.uid()))
  );

-- POINTS: read your own; nobody can write (complete_block() does it).
create policy "points: read own" on public.points_ledger
  for select to authenticated
  using (user_id = (select auth.uid()));

-- FRIENDSHIPS: both people can see the row and either can delete it
-- (cancel a request, decline it, or unfriend).
create policy "friendships: parties read" on public.friendships
  for select to authenticated
  using ((select auth.uid()) in (requester_id, addressee_id));

create policy "friendships: parties delete" on public.friendships
  for delete to authenticated
  using ((select auth.uid()) in (requester_id, addressee_id));

-- HANGOUT INVITES
create policy "invites: parties read" on public.hangout_invites
  for select to authenticated
  using ((select auth.uid()) in (from_user_id, to_user_id));

create policy "invites: send to friends" on public.hangout_invites
  for insert to authenticated
  with check (
    from_user_id = (select auth.uid())
    and status = 'pending'
    and public.are_friends(from_user_id, to_user_id)
  );

create policy "invites: recipient responds" on public.hangout_invites
  for update to authenticated
  using (to_user_id = (select auth.uid()) and status = 'pending')
  with check (to_user_id = (select auth.uid()) and status in ('accepted', 'declined'));

create policy "invites: sender cancels" on public.hangout_invites
  for delete to authenticated
  using (from_user_id = (select auth.uid()));

-- ---------------------------------------------------------------------------
-- 5. Functions the app calls (Supabase exposes them as RPC endpoints)
-- ---------------------------------------------------------------------------

-- Your own invite code (for the shareable link).
create function public.my_invite_code() returns text
language sql stable security definer set search_path = '' as $$
  select invite_code from public.profiles where id = (select auth.uid());
$$;

-- Send a friend request using someone's invite code. If they already sent
-- YOU a request, this accepts it instead (no awkward duplicate rows).
create function public.send_friend_request(code text) returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
  them uuid;
  existing public.friendships;
  new_id uuid;
begin
  if me is null then
    raise exception 'Not signed in' using errcode = '28000';
  end if;

  select id into them from public.profiles where invite_code = code;
  if them is null then
    raise exception 'Invite link not found' using errcode = 'P0002';
  end if;
  if them = me then
    raise exception 'That''s your own invite link' using errcode = '22023';
  end if;

  select * into existing from public.friendships f
  where least(f.requester_id, f.addressee_id) = least(me, them)
    and greatest(f.requester_id, f.addressee_id) = greatest(me, them);

  if found then
    if existing.status = 'pending' and existing.addressee_id = me then
      update public.friendships set status = 'accepted', accepted_at = now() where id = existing.id;
    end if;
    return existing.id;
  end if;

  insert into public.friendships (requester_id, addressee_id) values (me, them) returning id into new_id;
  return new_id;
end $$;

-- Accept or decline a request sent to you.
create function public.respond_friend_request(request_id uuid, accept boolean) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if accept then
    update public.friendships set status = 'accepted', accepted_at = now()
    where id = request_id and addressee_id = auth.uid() and status = 'pending';
  else
    delete from public.friendships
    where id = request_id and addressee_id = auth.uid() and status = 'pending';
  end if;
  if not found then
    raise exception 'Request not found' using errcode = 'P0002';
  end if;
end $$;

-- Mark one of YOUR blocks done and award points exactly once.
-- Returns the points awarded (0 if it was already done).
create function public.complete_block(block uuid) returns integer
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
  awarded integer := 0;
begin
  update public.blocks set status = 'done', completed_at = now()
  where id = block and user_id = me and status <> 'done';

  if found then
    insert into public.points_ledger (user_id, block_id, points, reason)
    values (me, block, 10, 'block_completed')
    on conflict (block_id) do nothing;
    if found then awarded := 10; end if;
  elsif not exists (select 1 from public.blocks where id = block and user_id = me) then
    raise exception 'Block not found' using errcode = 'P0002';
  end if;

  return awarded;
end $$;

-- Undo: back to planned, and take the points back.
create function public.uncomplete_block(block uuid) returns void
language plpgsql security definer set search_path = '' as $$
begin
  update public.blocks set status = 'planned', completed_at = null
  where id = block and user_id = auth.uid() and status = 'done';
  delete from public.points_ledger where block_id = block and user_id = auth.uid();
end $$;

-- A friend's BUSY TIMES in [range_start, range_end). Only start/end come
-- back: no titles, colors, or anything else. Returns nothing unless you
-- are friends. Recurring events are expanded day by day in the OWNER's
-- time zone, so "6 PM every Monday" stays 6 PM across daylight saving.
create function public.friend_busy_intervals(friend uuid, range_start timestamptz, range_end timestamptz)
returns table (starts_at timestamptz, ends_at timestamptz)
language sql stable security definer set search_path = '' as $$
  with allowed as (
    select public.are_friends((select auth.uid()), friend) as ok
  ),
  tz as (
    select s.time_zone from public.user_settings s where s.user_id = friend
  ),
  occurrences as (
    select
      (day + make_interval(mins => e.start_minute)) at time zone tz.time_zone as starts_at,
      (day + make_interval(mins => e.end_minute)) at time zone tz.time_zone as ends_at
    from public.events e
    cross join tz
    cross join lateral generate_series(
      greatest(e.start_date, (range_start at time zone tz.time_zone)::date - 1)::timestamp,
      least(coalesce(e.end_date, 'infinity'::date), (range_end at time zone tz.time_zone)::date + 1)::timestamp,
      interval '1 day'
    ) as g(day)
    where e.user_id = friend
      and (
        (cardinality(e.weekdays) = 0 and day::date = e.start_date)
        or extract(isodow from day)::smallint = any (e.weekdays)
      )
  ),
  busy as (
    select starts_at, ends_at from occurrences
    union all
    select b.starts_at, b.ends_at from public.blocks b
    where b.user_id = friend and b.status in ('planned', 'done')
  )
  select busy.starts_at, busy.ends_at from busy, allowed
  where allowed.ok
    and busy.starts_at < range_end
    and busy.ends_at > range_start
  order by 1;
$$;

-- Functions are callable by everyone by default, and Supabase's default
-- privileges also grant them to `anon`. Lock them down to signed-in users
-- (and nobody at all for the internal trigger function).
revoke all on function public.are_friends(uuid, uuid) from public, anon;
revoke all on function public.has_friendship(uuid, uuid) from public, anon;
revoke all on function public.my_invite_code() from public, anon;
revoke all on function public.send_friend_request(text) from public, anon;
revoke all on function public.respond_friend_request(uuid, boolean) from public, anon;
revoke all on function public.complete_block(uuid) from public, anon;
revoke all on function public.uncomplete_block(uuid) from public, anon;
revoke all on function public.friend_busy_intervals(uuid, timestamptz, timestamptz) from public, anon;
revoke all on function public.handle_new_user() from public, anon;
revoke all on function public.set_updated_at() from public, anon;
revoke all on function public.validate_time_zone() from public, anon;
grant execute on function public.are_friends(uuid, uuid) to authenticated;
grant execute on function public.has_friendship(uuid, uuid) to authenticated;
grant execute on function public.my_invite_code() to authenticated;
grant execute on function public.send_friend_request(text) to authenticated;
grant execute on function public.respond_friend_request(uuid, boolean) to authenticated;
grant execute on function public.complete_block(uuid) to authenticated;
grant execute on function public.uncomplete_block(uuid) to authenticated;
grant execute on function public.friend_busy_intervals(uuid, timestamptz, timestamptz) to authenticated;
